    if v_str == '1m-5m': return 1000000 <= vol <= 5000000
    if v_str == '>5m': return vol > 5000000
    return True

def match_fraud(ratio, f_str):
    if f_str is None: return True
    if f_str == '<7.2%': return ratio < 0.072
    if f_str == '7.2%-7.7%': return 0.072 <= ratio <= 0.077
    if f_str == '7.7%-8.3%': return 0.077 <= ratio <= 0.083
    if f_str == '>8.3%': return ratio > 0.083
    return True

def get_month(day_of_year):
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    cumulative = 0
    for i, d in enumerate(days_in_month):
        cumulative += d
        if day_of_year <= cumulative:
            return i + 1
    return 12

def solve():
    with open('/data/fees.json', 'r') as f:
        fees = json.load(f)

    belles_payments = []
    with open('/data/payments.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['merchant'] == 'Belles_cookbook_store' and row['year'] == '2023':
                belles_payments.append(row)

    monthly_stats = {}
    for p in belles_payments:
        m = get_month(int(p['day_of_year']))
        if m not in monthly_stats:
            monthly_stats[m] = {'total_vol': 0.0, 'fraud_vol': 0.0}
        amount = float(p['eur_amount'])
        monthly_stats[m]['total_vol'] += amount
        if p['has_fraudulent_dispute'] == 'True':
            monthly_stats[m]['fraud_vol'] += amount

    monthly_metrics = {}
    for m, stats in monthly_stats.items():
        vol = stats['total_vol']
        fraud_ratio = stats['fraud_vol'] / vol if vol > 0 else 0
        monthly_metrics[m] = (vol, fraud_ratio)
        print(f"Month {m}: vol={vol}, fraud={fraud_ratio}")

    merchant_account_type = "R"
    merchant_capture_delay = "<3" # "1" -> "<3"

    def calculate_total_fees(mcc):
        total_fees = 0.0
        for p in belles_payments:
            m = get_month(int(p['day_of_year']))
            vol, fraud_ratio = monthly_metrics[m]

            trans_val = float(p['eur_amount'])
            is_credit = p['is_credit'] == 'True'
            aci = p['aci']
            intracountry = p['issuing_country'] == p['acquirer_country']
            card_scheme = p['card_scheme']

            for rule in fees:
                if rule['card_scheme'] is not None and rule['card_scheme'] != card_scheme:
                    continue
                if rule['account_type'] is not None and len(rule['account_type']) > 0:
                    if merchant_account_type not in rule['account_type']:
                        continue
                if rule['capture_delay'] is not None and rule['capture_delay'] != merchant_capture_delay:
                    continue
                if not match_volume(vol, rule['monthly_volume']):
                    continue
                if not match_fraud(fraud_ratio, rule['monthly_fraud_level']):
                    continue
                if rule['merchant_category_code'] is not None and len(rule['merchant_category_code']) > 0:
                    if mcc not in rule['merchant_category_code']:
                        continue
                if rule['is_credit'] is not None and rule['is_credit'] != is_credit:
                    continue
                if rule['aci'] is not None and len(rule['aci']) > 0:
                    if aci not in rule['aci']:
                        continue
                if rule['intracountry'] is not None and rule['intracountry'] != intracountry:
                    continue

                fee = rule['fixed_amount'] + (rule['rate'] * trans_val / 10000.0)
                total_fees += fee
        return total_fees

    fees_7997 = calculate_total_fees(7997)
    fees_5411 = calculate_total_fees(5411)

    delta = fees_5411 - fees_7997
